"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[62192],{22940:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponController","desc":"Bootstrap that drives every equipped weapon. Watches the local character for\\nTool equip (Tool parented to character) / unequip (removed), looks up the\\nTool\'s `WeaponConfig` entry by name, and dispatches to the category handler.\\nConnects `Tool.Activated` to the handler\'s `OnActivate`. One Janitor per\\nequipped Tool; one per character. Fires `Signals.WeaponEquipped/Unequipped`\\nfor the HUD, and drives the aim/shooting camera via\\n`Signals.RequestShootingCamera` on equip/unequip (same intent as GrabHook).","realm":["Client"],"source":{"line":14,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponController.client.luau"}}')}}]);